import{_ as d,a0 as n,w as o,s as l,ao as c,I as p,x as i,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在你的 Fedora 終端上播放音樂 | LCTT x X-CMD","titleTemplate":false,"description":"在你的 Fedora 終端上播放音樂 | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在你的 Fedora 終端上播放音樂 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在你的 Fedora 終端上播放音樂 | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20200210 Playing Music on your Fedora Terminal with MPD and ncmpcpp","title":"在你的 Fedora 終端上播放音樂","tag":"202002","desc":""},"relativePath":"202002/20200210 Playing Music on your Fedora Terminal with MPD and ncmpcpp.md","filePath":"[post].md"}'),r={name:"202002/20200210 Playing Music on your Fedora Terminal with MPD and ncmpcpp.md"};function h(g,e,u,m,k,f){const s=n("Link");return o(),l("div",null,[e[15]||(e[15]=c(`<h1 id="在你的-fedora-終端上播放音樂" tabindex="-1">在你的 Fedora 終端上播放音樂 <a class="header-anchor" href="#在你的-fedora-終端上播放音樂" aria-label="Permalink to “在你的 Fedora 終端上播放音樂”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/02/play_music_mpd-816x346.png" alt=""></p><p>MPD（Music Playing Daemon），顧名思義，是一個音樂（Music）播放（Playing）守護進程（Daemon）。它可以播放音樂，並且作為一個守護進程，任何軟件都可以與之交互並播放聲音，包括一些 CLI 客户端。</p><p>其中一個被稱為 <code>ncmpcpp</code>，它是對之前 <code>ncmpc</code> 工具的改進。名字的變化與編寫它們的語言沒有太大關係：都是 C++，而之所以被稱為 <code>ncmpcpp</code>，因為它是 “NCurses Music Playing Client Plus Plus”。 緣故</p><h3 id="安裝-mpd-和-ncmpcpp" tabindex="-1">安裝 MPD 和 ncmpcpp <a class="header-anchor" href="#安裝-mpd-和-ncmpcpp" aria-label="Permalink to “安裝 MPD 和 ncmpcpp”">​</a></h3><p><code>ncmpmpcc</code> 的客户端可以從官方 Fedora 庫中通過 <code>dnf</code> 命令直接安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install ncmpcpp</span></span></code></pre></div><p>另一方面，MPD 必須從 RPMFusion free 庫安裝，你可以通過運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install https://download1.rpmfusion.org/free/fedora/rpmfusion-free-release-$(rpm -E %fedora).noarch.rpm</span></span></code></pre></div><p>然後你可以運行下面的命令安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install mpd</span></span></code></pre></div><h3 id="配置並啓用-mpd" tabindex="-1">配置並啓用 MPD <a class="header-anchor" href="#配置並啓用-mpd" aria-label="Permalink to “配置並啓用 MPD”">​</a></h3><p>設置 MPD 最簡單的方法是以普通用户的身份運行它。默認情況是以專用 <code>mpd</code> 用户的身份運行它，但這會導致各種權限問題。</p><p>在運行它之前，我們需要創建一個本地配置文件，允許我們作為普通用户運行。</p><p>首先在 <code>~/.config</code> 裏創建一個名叫 <code>mpd</code> 的目錄:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir ~/.config/mpd</span></span></code></pre></div><p>將配置文件拷貝到此目錄下:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp /etc/mpd.conf ~/.config/mpd</span></span></code></pre></div><p>然後用 <code>vim</code>、<code>nano</code> 或 <code>gedit</code> 之類的軟件編輯它:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ nano ~/.config/mpd/mpd.conf</span></span></code></pre></div><p>我建議你通讀所有內容，檢查是否有任何需要做的事情，但對於大多數設置你都可以刪除，只需保留以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>db_file &quot;~/.config/mpd/mpd.db&quot;</span></span>
<span class="line"><span>log_file &quot;syslog&quot;</span></span></code></pre></div><p>現在你可以運行它了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mpd</span></span></code></pre></div><p>沒有報錯，這將在後台啓動 MPD 守護進程。</p><h3 id="使用-ncmpcpp" tabindex="-1">使用 ncmpcpp <a class="header-anchor" href="#使用-ncmpcpp" aria-label="Permalink to “使用 ncmpcpp”">​</a></h3><p>只需運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncmpcpp</span></span></code></pre></div><p>你將在終端中看到一個由 ncurses 所支持的圖形用户界面。</p><p>按下 <code>4</code> 鍵，然後就可以看到本地的音樂目錄，用方向鍵進行選擇並按下回車進行播放。</p><p>多播放幾個歌曲就會創建一個<em>播放列表</em>，讓你可以使用 <code>&gt;</code> 鍵（不是右箭頭, 是右尖括號）移動到下一首，並使用 <code>&lt;</code> 返回上一首。<code>+</code> 和 <code>–</code> 鍵可以調節音量。<code>Q</code> 鍵可以讓你退出 <code>ncmpcpp</code> 但不停止播放音樂。你可以按下 <code>P</code> 來控制暫停和播放。</p><p>你可以按下 <code>1</code> 鍵來查看當前播放列表（這是默認的視圖）。從這個視圖中，你可以按 <code>i</code> 查看有關當前歌曲的信息（標籤）。按 <code>6</code> 可更改當前歌曲的標籤。</p><p>按 <code>\\</code> 按鈕將在視圖頂部添加（或刪除）信息面板。在左上角，你可以看到如下的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[------]</span></span></code></pre></div><p>按下 <code>r</code>、<code>z</code>、<code>y</code>、<code>R</code>、<code>x</code> 將會分別切換到 <code>repeat</code>、<code>random</code>、<code>single</code>、<code>consume</code> 和 <code>crossfade</code> 等播放模式，並將這個小指示器中的 <code>–</code> 字符替換為選定模式。</p><p>按下 <code>F1</code> 鍵將會顯示一些幫助文檔，包含一系列的鍵綁定列表，因此無需在此處列出完整列表。所以繼續吧！做一個極客，在你的終端上播放音樂！</p><hr>`,37)),p("p",null,[e[1]||(e[1]=i("via: ",-1)),a(s,{href:"https://fedoramagazine.org/playing-music-on-your-fedora-terminal-with-mpd-and-ncmpcpp/"},{default:t(()=>[...e[0]||(e[0]=[i("https://fedoramagazine.org/playing-music-on-your-fedora-terminal-with-mpd-and-ncmpcpp/",-1)])]),_:1})]),p("p",null,[e[6]||(e[6]=i("作者：",-1)),a(s,{href:"https://fedoramagazine.org/author/carzacc/"},{default:t(()=>[...e[2]||(e[2]=[i("Carmine Zaccagnino",-1)])]),_:1}),e[7]||(e[7]=i(" 選題：",-1)),a(s,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[3]||(e[3]=[i("lujun9972",-1)])]),_:1}),e[8]||(e[8]=i(" 譯者：",-1)),a(s,{href:"https://github.com/chai-yuan"},{default:t(()=>[...e[4]||(e[4]=[i("chai-yuan",-1)])]),_:1}),e[9]||(e[9]=i(" 校對：",-1)),a(s,{href:"https://github.com/wxy"},{default:t(()=>[...e[5]||(e[5]=[i("wxy",-1)])]),_:1})]),p("p",null,[e[12]||(e[12]=i("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[10]||(e[10]=[i("LCTT",-1)])]),_:1}),e[13]||(e[13]=i(" 原創編譯，",-1)),a(s,{href:"https://linux.cn/"},{default:t(()=>[...e[11]||(e[11]=[i("Linux中國",-1)])]),_:1}),e[14]||(e[14]=i(" 榮譽推出",-1))])])}const P=d(r,[["render",h]]);export{C as __pageData,P as default};
